// Custom Worker entrypoint: wraps the OpenNext-generated handler and adds the
// cron scheduler plus the audit Workflow class. `opennextjs-cloudflare build`
// must run before wrangler so that ./.open-next/worker.js exists.

// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as openNextHandler } from "./.open-next/worker.js";
import { runScheduler } from "./src/audit/scheduler";

export { AuditRunWorkflow } from "./src/audit/workflow";
// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

export default {
  fetch: openNextHandler.fetch,

  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(runScheduler(env, new Date(controller.scheduledTime)));
  },
} satisfies ExportedHandler<CloudflareEnv>;
